FrameBuf:: Fade(void)
{
	const int max = 32;
	Uint16 ramp[256];   

	for ( int j = 1; j <= max; j++ ) {
		int v = faded ? j : max - j + 1;
		for ( int i = 0; i < 256; i++ ) {
			ramp[i] = (i * v / max) << 8;
		}
		SDL_SetGammaRamp(ramp, ramp, ramp);
		SDL_Delay(10);
	}
	faded = !faded;

        if ( faded ) {
		for ( int i = 0; i < 256; i++ ) {
			ramp[i] = 0;
		}
		SDL_SetGammaRamp(ramp, ramp, ramp);
	}
} 

